INSERT INTO notifications (user_id, type, event_title, community_id, event_id, actor_user_id)
SELECT m.user_id, 'late_cancellation', e.title, e.community_id, e.id, #{actorUserId}
FROM events e
JOIN memberships m ON m.community_id = e.community_id
WHERE e.id = #{eventId}
  AND m.role IN ('owner', 'staff')
  AND m.user_id <> #{operatorUserId}

